namespace sv_98a879f2996744bca30bd3c60bd6c505.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service (per-circuit) that holds theme state and notifies subscribers on change.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#6366f1";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever Theme or AccentColor changes.
    /// Components subscribe to this and call StateHasChanged().
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@rendermode InteractiveServer
@inject sv_98a879f2996744bca30bd3c60bd6c505.Services.ThemeService ThemeService
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetIcon() @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetIcon() => ThemeService.Theme switch
    {
        sv_98a879f2996744bca30bd3c60bd6c505.Services.ThemeMode.Light => "☀️",
        sv_98a879f2996744bca30bd3c60bd6c505.Services.ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject sv_98a879f2996744bca30bd3c60bd6c505.Services.ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="settings-panel">
    <h3>Theme</h3>
    <div>
        @foreach (var mode in Enum.GetValues<sv_98a879f2996744bca30bd3c60bd6c505.Services.ThemeMode>())
        {
            <label style="margin-right: 1rem;">
                <input type="radio" name="theme"
                       value="@mode"
                       checked="@(ThemeService.Theme == mode)"
                       @onchange="() => ThemeService.Theme = mode" />
                @mode
            </label>
        }
    </div>

    <h3 style="margin-top: 1rem;">Accent Color</h3>
    <input type="color"
           value="@ThemeService.AccentColor"
           @onchange="HandleColorChange" />
    <span style="color: @ThemeService.AccentColor; margin-left: 0.5rem;">
        @ThemeService.AccentColor
    </span>
</div>

<p style="margin-top: 2rem; color: @ThemeService.AccentColor;">
    <strong>Preview:</strong> This text uses your accent color. The header indicator updates in real time.
</p>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleColorChange(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#6366f1";
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

